62	class DelegateProviders {
63	 public:
64	  DelegateProviders() : delegate_list_util_(&params_) {
65	    delegate_list_util_.AddAllDelegateParams();
66	    delegate_list_util_.AppendCmdlineFlags(flags_);
67	
68	    // Remove the "help" flag to avoid printing "--help=false"
69	    params_.RemoveParam("help");
