73	  // Initialize delegate-related parameters from parsing command line arguments,
74	  // and remove the matching arguments from (*argc, argv). Returns true if all
75	  // recognized arg values are parsed correctly.
76	  bool InitFromCmdlineArgs(int* argc, const char** argv) {
77	    // Note if '--help' is in argv, the Flags::Parse return false,
78	    // see the return expression in Flags::Parse.
79	    return Flags::Parse(argc, argv, flags_);
80	  }
81	
82	  // According to passed-in settings `s`, this function sets corresponding
83	  // parameters that are defined by various delegate execution providers. See
84	  // lite/tools/delegates/README.md for the full list of parameters defined.
85	  void MergeSettingsIntoParams(const Settings& s) {
86	    // Parse settings related to GPU delegate.
87	    // Note that GPU delegate does support OpenCL. 'gl_backend' was introduced
88	    // when the GPU delegate only supports OpenGL. Therefore, we consider
89	    // setting 'gl_backend' to true means using the GPU delegate.
90	    if (s.gl_backend) {
91	      if (!params_.HasParam("use_gpu")) {
92	        LOG(WARN) << "GPU delegate execution provider isn't linked or GPU "
93	                     "delegate isn't supported on the platform!";
94	      } else {
95	        params_.Set<bool>("use_gpu", true);
96	        // The parameter "gpu_inference_for_sustained_speed" isn't available for
97	        // iOS devices.
98	        if (params_.HasParam("gpu_inference_for_sustained_speed")) {
99	          params_.Set<bool>("gpu_inference_for_sustained_speed", true);
100	        }
101	        params_.Set<bool>("gpu_precision_loss_allowed", s.allow_fp16);
102	      }
103	    }
104	
105	    // Parse settings related to NNAPI delegate.
106	    if (s.accel) {
107	      if (!params_.HasParam("use_nnapi")) {
108	        LOG(WARN) << "NNAPI delegate execution provider isn't linked or NNAPI "
109	                     "delegate isn't supported on the platform!";
110	      } else {
111	        params_.Set<bool>("use_nnapi", true);
112	        params_.Set<bool>("nnapi_allow_fp16", s.allow_fp16);
113	      }
114	    }
115	
116	    // Parse settings related to Hexagon delegate.
117	    if (s.hexagon_delegate) {
118	      if (!params_.HasParam("use_hexagon")) {
119	        LOG(WARN) << "Hexagon delegate execution provider isn't linked or "
120	                     "Hexagon delegate isn't supported on the platform!";
121	      } else {
122	        params_.Set<bool>("use_hexagon", true);
123	        params_.Set<bool>("hexagon_profiling", s.profiling);
124	      }
125	    }
126	
127	    // Parse settings related to XNNPACK delegate.
128	    if (s.xnnpack_delegate) {
129	      if (!params_.HasParam("use_xnnpack")) {
130	        LOG(WARN) << "XNNPACK delegate execution provider isn't linked or "
131	                     "XNNPACK delegate isn't supported on the platform!";
132	      } else {
133	        params_.Set<bool>("use_xnnpack", true);
134	        params_.Set<int32_t>("num_threads", s.number_of_threads);
135	      }
136	    }
137	  }
