162	// Takes a file name, and loads a list of labels from it, one per line, and
163	// returns a vector of the strings. It pads with empty strings so the length
164	// of the result is a multiple of 16, because our model expects that.
165	TfLiteStatus ReadLabelsFile(const string& file_name,
166	                            std::vector<string>* result,
167	                            size_t* found_label_count) {
168	  std::ifstream file(file_name);
169	  if (!file) {
170	    LOG(ERROR) << "Labels file " << file_name << " not found";
171	    return kTfLiteError;
172	  }
173	  result->clear();
174	  string line;
175	  while (std::getline(file, line)) {
176	    result->push_back(line);
177	  }
178	  *found_label_count = result->size();
179	  const int padding = 16;
180	  while (result->size() % padding) {
181	    result->emplace_back();
182	  }
183	  return kTfLiteOk;
184	}
