186	void PrintProfilingInfo(const profiling::ProfileEvent* e,
187	                        uint32_t subgraph_index, uint32_t op_index,
188	                        TfLiteRegistration registration) {
189	  // output something like
190	  // time (ms) , Node xxx, OpCode xxx, symbolic name
191	  //      5.352, Node   5, OpCode   4, DEPTHWISE_CONV_2D
192	
193	  LOG(INFO) << std::fixed << std::setw(10) << std::setprecision(3)
194	            << (e->elapsed_time) / 1000.0 << ", Subgraph " << std::setw(3)
195	            << std::setprecision(3) << subgraph_index << ", Node "
196	            << std::setw(3) << std::setprecision(3) << op_index << ", OpCode "
197	            << std::setw(3) << std::setprecision(3) << registration.builtin_code
198	            << ", "
199	            << EnumNameBuiltinOperator(
200	                   static_cast<BuiltinOperator>(registration.builtin_code));
201	}
