203	void RunInference(Settings* settings,
204	                  const DelegateProviders& delegate_providers) {
205	  if (!settings->model_name.c_str()) {
206	    LOG(ERROR) << "no model file name";
207	    exit(-1);
208	  }
209	
210	  std::unique_ptr<tflite::FlatBufferModel> model;
211	  std::unique_ptr<tflite::Interpreter> interpreter;
212	  model = tflite::FlatBufferModel::BuildFromFile(settings->model_name.c_str());
213	  if (!model) {
214	    LOG(ERROR) << "Failed to mmap model " << settings->model_name;
215	    exit(-1);
216	  }
217	  settings->model = model.get();
218	  LOG(INFO) << "Loaded model " << settings->model_name;
219	  model->error_reporter();
220	  LOG(INFO) << "resolved reporter";
221	
222	  tflite::ops::builtin::BuiltinOpResolver resolver;
223	
224	  tflite::InterpreterBuilder(*model, resolver)(&interpreter);
225	  if (!interpreter) {
226	    LOG(ERROR) << "Failed to construct interpreter";
227	    exit(-1);
228	  }
229	
230	  interpreter->SetAllowFp16PrecisionForFp32(settings->allow_fp16);
231	
232	  if (settings->verbose) {
233	    LOG(INFO) << "tensors size: " << interpreter->tensors_size();
234	    LOG(INFO) << "nodes size: " << interpreter->nodes_size();
235	    LOG(INFO) << "inputs: " << interpreter->inputs().size();
236	    LOG(INFO) << "input(0) name: " << interpreter->GetInputName(0);
237	
238	    int t_size = interpreter->tensors_size();
239	    for (int i = 0; i < t_size; i++) {
240	      if (interpreter->tensor(i)->name)
241	        LOG(INFO) << i << ": " << interpreter->tensor(i)->name << ", "
242	                  << interpreter->tensor(i)->bytes << ", "
243	                  << interpreter->tensor(i)->type << ", "
244	                  << interpreter->tensor(i)->params.scale << ", "
245	                  << interpreter->tensor(i)->params.zero_point;
246	    }
247	  }
248	
249	  if (settings->number_of_threads != -1) {
250	    interpreter->SetNumThreads(settings->number_of_threads);
251	  }
252	
253	  int image_width = 224;
254	  int image_height = 224;
255	  int image_channels = 3;
256	  std::vector<uint8_t> in = read_bmp(settings->input_bmp_name, &image_width,
257	                                     &image_height, &image_channels, settings);
258	
259	  int input = interpreter->inputs()[0];
260	  if (settings->verbose) LOG(INFO) << "input: " << input;
261	
262	  const std::vector<int> inputs = interpreter->inputs();
263	  const std::vector<int> outputs = interpreter->outputs();
264	
265	  if (settings->verbose) {
266	    LOG(INFO) << "number of inputs: " << inputs.size();
267	    LOG(INFO) << "number of outputs: " << outputs.size();
268	  }
269	
270	  auto profiler = std::make_unique<profiling::Profiler>(
271	      settings->max_profiling_buffer_entries);
272	  interpreter->SetProfiler(profiler.get());
273	
274	  auto delegates = delegate_providers.CreateAllDelegates();
275	  for (auto& delegate : delegates) {
276	    const auto delegate_name = delegate.provider->GetName();
277	    if (interpreter->ModifyGraphWithDelegate(std::move(delegate.delegate)) !=
278	        kTfLiteOk) {
279	      LOG(ERROR) << "Failed to apply " << delegate_name << " delegate.";
280	      exit(-1);
281	    } else {
282	      LOG(INFO) << "Applied " << delegate_name << " delegate.";
283	    }
284	  }
285	
286	  if (interpreter->AllocateTensors() != kTfLiteOk) {
287	    LOG(ERROR) << "Failed to allocate tensors!";
288	    exit(-1);
289	  }
290	
291	  if (settings->verbose) PrintInterpreterState(interpreter.get());
292	
293	  // get input dimension from the input tensor metadata
294	  // assuming one input only
295	  TfLiteIntArray* dims = interpreter->tensor(input)->dims;
296	  int wanted_height = dims->data[1];
297	  int wanted_width = dims->data[2];
298	  int wanted_channels = dims->data[3];
299	
300	  settings->input_type = interpreter->tensor(input)->type;
301	  switch (settings->input_type) {
302	    case kTfLiteFloat32:
303	      resize<float>(interpreter->typed_tensor<float>(input), in.data(),
304	                    image_height, image_width, image_channels, wanted_height,
305	                    wanted_width, wanted_channels, settings);
306	      break;
307	    case kTfLiteInt8:
308	      resize<int8_t>(interpreter->typed_tensor<int8_t>(input), in.data(),
309	                     image_height, image_width, image_channels, wanted_height,
310	                     wanted_width, wanted_channels, settings);
311	      break;
312	    case kTfLiteUInt8:
313	      resize<uint8_t>(interpreter->typed_tensor<uint8_t>(input), in.data(),
314	                      image_height, image_width, image_channels, wanted_height,
315	                      wanted_width, wanted_channels, settings);
316	      break;
317	    default:
318	      LOG(ERROR) << "cannot handle input type "
319	                 << interpreter->tensor(input)->type << " yet";
320	      exit(-1);
321	  }
322	
323	  if (settings->profiling) profiler->StartProfiling();
324	  for (int i = 0; i < settings->number_of_warmup_runs; i++) {
325	    if (interpreter->Invoke() != kTfLiteOk) {
326	      LOG(ERROR) << "Failed to invoke tflite!";
327	      exit(-1);
328	    }
329	  }
330	
331	  struct timeval start_time, stop_time;
332	  gettimeofday(&start_time, nullptr);
333	  for (int i = 0; i < settings->loop_count; i++) {
334	    if (interpreter->Invoke() != kTfLiteOk) {
335	      LOG(ERROR) << "Failed to invoke tflite!";
336	      exit(-1);
337	    }
338	  }
339	  gettimeofday(&stop_time, nullptr);
340	  LOG(INFO) << "invoked";
341	  LOG(INFO) << "average time: "
342	            << (get_us(stop_time) - get_us(start_time)) /
343	                   (settings->loop_count * 1000)
344	            << " ms";
345	
346	  if (settings->profiling) {
347	    profiler->StopProfiling();
348	    auto profile_events = profiler->GetProfileEvents();
349	    for (int i = 0; i < profile_events.size(); i++) {
350	      auto subgraph_index = profile_events[i]->extra_event_metadata;
351	      auto op_index = profile_events[i]->event_metadata;
352	      const auto subgraph = interpreter->subgraph(subgraph_index);
353	      const auto node_and_registration =
354	          subgraph->node_and_registration(op_index);
355	      const TfLiteRegistration registration = node_and_registration->second;
356	      PrintProfilingInfo(profile_events[i], subgraph_index, op_index,
357	                         registration);
358	    }
359	  }
360	
361	  const float threshold = 0.001f;
362	
363	  std::vector<std::pair<float, int>> top_results;
364	
365	  int output = interpreter->outputs()[0];
366	  TfLiteIntArray* output_dims = interpreter->tensor(output)->dims;
367	  // assume output dims to be something like (1, 1, ... ,size)
368	  auto output_size = output_dims->data[output_dims->size - 1];
369	  switch (interpreter->tensor(output)->type) {
370	    case kTfLiteFloat32:
371	      get_top_n<float>(interpreter->typed_output_tensor<float>(0), output_size,
372	                       settings->number_of_results, threshold, &top_results,
373	                       settings->input_type);
374	      break;
375	    case kTfLiteInt8:
376	      get_top_n<int8_t>(interpreter->typed_output_tensor<int8_t>(0),
377	                        output_size, settings->number_of_results, threshold,
378	                        &top_results, settings->input_type);
379	      break;
380	    case kTfLiteUInt8:
381	      get_top_n<uint8_t>(interpreter->typed_output_tensor<uint8_t>(0),
382	                         output_size, settings->number_of_results, threshold,
383	                         &top_results, settings->input_type);
384	      break;
385	    default:
386	      LOG(ERROR) << "cannot handle output type "
387	                 << interpreter->tensor(output)->type << " yet";
388	      exit(-1);
389	  }
390	
391	  std::vector<string> labels;
392	  size_t label_count;
393	
394	  if (ReadLabelsFile(settings->labels_file_name, &labels, &label_count) !=
395	      kTfLiteOk)
396	    exit(-1);
397	
398	  for (const auto& result : top_results) {
399	    const float confidence = result.first;
400	    const int index = result.second;
401	    LOG(INFO) << confidence << ": " << index << " " << labels[index];
402	  }
403	
404	  // Destory the interpreter earlier than delegates objects.
405	  interpreter.reset();
406	}
