416	      << "\t--gl_backend, -g: [0|1]: use GL GPU Delegate on Android\n"
417	      << "\t--hexagon_delegate, -j: [0|1]: use Hexagon Delegate on Android\n"
418	      << "\t--input_mean, -b: input mean\n"
419	      << "\t--input_std, -s: input standard deviation\n"
420	      << "\t--image, -i: image_name.bmp\n"
421	      << "\t--labels, -l: labels for the model\n"
422	      << "\t--tflite_model, -m: model_name.tflite\n"
423	      << "\t--profiling, -p: [0|1], profiling or not\n"
424	      << "\t--num_results, -r: number of results to show\n"
425	      << "\t--threads, -t: number of threads\n"
426	      << "\t--verbose, -v: [0|1] print more information\n"
427	      << "\t--warmup_runs, -w: number of warmup runs\n"
428	      << "\t--xnnpack_delegate, -x [0:1]: xnnpack delegate\n"
429	      << "\t--help, -h: Print this help message\n";
