432	int Main(int argc, char** argv) {
433	  DelegateProviders delegate_providers;
434	  bool parse_result = delegate_providers.InitFromCmdlineArgs(
435	      &argc, const_cast<const char**>(argv));
436	  if (!parse_result) {
437	    display_usage(delegate_providers);
438	    return EXIT_FAILURE;
439	  }
440	
441	  Settings s;
442	
443	  int c;
444	  while (true) {
445	    static struct option long_options[] = {
446	        {"accelerated", required_argument, nullptr, 'a'},
447	        {"allow_fp16", required_argument, nullptr, 'f'},
448	        {"count", required_argument, nullptr, 'c'},
449	        {"verbose", required_argument, nullptr, 'v'},
450	        {"image", required_argument, nullptr, 'i'},
451	        {"labels", required_argument, nullptr, 'l'},
452	        {"tflite_model", required_argument, nullptr, 'm'},
453	        {"profiling", required_argument, nullptr, 'p'},
454	        {"threads", required_argument, nullptr, 't'},
455	        {"input_mean", required_argument, nullptr, 'b'},
456	        {"input_std", required_argument, nullptr, 's'},
457	        {"num_results", required_argument, nullptr, 'r'},
458	        {"max_profiling_buffer_entries", required_argument, nullptr, 'e'},
459	        {"warmup_runs", required_argument, nullptr, 'w'},
460	        {"gl_backend", required_argument, nullptr, 'g'},
461	        {"hexagon_delegate", required_argument, nullptr, 'j'},
462	        {"xnnpack_delegate", required_argument, nullptr, 'x'},
463	        {"help", no_argument, nullptr, 'h'},
464	        {nullptr, 0, nullptr, 0}};
465	
466	    /* getopt_long stores the option index here. */
467	    int option_index = 0;
468	
469	    c = getopt_long(argc, argv, "a:b:c:d:e:f:g:i:j:l:m:p:r:s:t:v:w:x:h",
470	                    long_options, &option_index);
471	
472	    /* Detect the end of the options. */
473	    if (c == -1) break;
474	
475	    switch (c) {
476	      case 'a':
477	        s.accel = strtol(optarg, nullptr, 10);  // NOLINT(runtime/deprecated_fn)
478	        break;
479	      case 'b':
480	        s.input_mean = strtod(optarg, nullptr);
481	        break;
482	      case 'c':
483	        s.loop_count =
484	            strtol(optarg, nullptr, 10);  // NOLINT(runtime/deprecated_fn)
485	        break;
486	      case 'e':
487	        s.max_profiling_buffer_entries =
488	            strtol(optarg, nullptr, 10);  // NOLINT(runtime/deprecated_fn)
489	        break;
490	      case 'f':
491	        s.allow_fp16 =
492	            strtol(optarg, nullptr, 10);  // NOLINT(runtime/deprecated_fn)
493	        break;
494	      case 'g':
495	        s.gl_backend =
496	            strtol(optarg, nullptr, 10);  // NOLINT(runtime/deprecated_fn)
497	        break;
498	      case 'i':
499	        s.input_bmp_name = optarg;
500	        break;
501	      case 'j':
502	        s.hexagon_delegate = optarg;
503	        break;
504	      case 'l':
505	        s.labels_file_name = optarg;
506	        break;
507	      case 'm':
508	        s.model_name = optarg;
509	        break;
510	      case 'p':
511	        s.profiling =
512	            strtol(optarg, nullptr, 10);  // NOLINT(runtime/deprecated_fn)
513	        break;
514	      case 'r':
515	        s.number_of_results =
516	            strtol(optarg, nullptr, 10);  // NOLINT(runtime/deprecated_fn)
517	        break;
518	      case 's':
519	        s.input_std = strtod(optarg, nullptr);
520	        break;
521	      case 't':
522	        s.number_of_threads = strtol(  // NOLINT(runtime/deprecated_fn)
523	            optarg, nullptr, 10);
524	        break;
525	      case 'v':
526	        s.verbose =
527	            strtol(optarg, nullptr, 10);  // NOLINT(runtime/deprecated_fn)
528	        break;
529	      case 'w':
530	        s.number_of_warmup_runs =
531	            strtol(optarg, nullptr, 10);  // NOLINT(runtime/deprecated_fn)
532	        break;
533	      case 'x':
534	        s.xnnpack_delegate =
535	            strtol(optarg, nullptr, 10);  // NOLINT(runtime/deprecated_fn)
536	        break;
537	      case 'h':
538	      case '?':
539	        /* getopt_long already printed an error message. */
540	        display_usage(delegate_providers);
541	        exit(-1);
542	      default:
543	        exit(-1);
544	    }
545	  }
546	
547	  delegate_providers.MergeSettingsIntoParams(s);
548	  RunInference(&s, delegate_providers);
549	  return 0;
550	}
551	
552	}  // namespace label_image
553	}  // namespace tflite
554	
555	int main(int argc, char** argv) {
556	  return tflite::label_image::Main(argc, argv);
557	}
